import hashlib
import json
from pathlib import Path
from capture import ROOT, RUN, scan

def load(path):
    return json.loads((RUN/path).read_bytes())
def save(path,value):
    with (RUN/path).open('x',encoding='utf-8') as stream:
        json.dump(value,stream,ensure_ascii=False,indent=2)

def effects(before,after):
    left={row['path']:row for row in before['files']}
    right={row['path']:row for row in after['files']}
    return [name for name in sorted(left.keys()|right.keys()) if left.get(name)!=right.get(name)]

