        plan=json.loads((directory/'plan.json').read_bytes())
        changed=effects(plan['before'],result['after'])
        allowed=all(name.startswith(('.trial-output/','out/')) for name in changed)
        native.append({'attempt':directory.name,'exit_code':result['exit_code'],'termination':result['termination'],'changed_paths':changed,'within_trial_write_set':allowed,'producer_unchanged':result.get('producer_unchanged')})
